import type { Metadata } from "next";
import { buildPageMetadata, seo } from "@/content/seo";
import { PageHero } from "@/components/sections/PageHero";
import { Container } from "@/components/ui/Container";
import { footerContent } from "@/content/site";

export const metadata: Metadata = buildPageMetadata(seo.privacyPolicy);

export default function PrivacyPolicyPage() {
  return (
    <>
      <PageHero
        eyebrow="Legal"
        heading="Privacy Policy"
        body="How Goldapples Media Associates handles the information you share with us — through this site, a consultation request or a programme brief."
        lead="We are committed to protecting your data and maintaining trust."
      />
      <section className="py-24 lg:py-32">
        <Container className="max-w-[70ch]">
          <p className="text-steel text-lg leading-relaxed">
            Our full privacy policy is being finalised. In the meantime, if you have
            questions about how Goldapples Media Associates handles the information you
            share with us — through this site, a consultation request or a programme brief
            — please contact us directly at{" "}
            <a
              href={`mailto:${footerContent.email}`}
              className="text-ink hover:text-gold-deep underline"
            >
              {footerContent.email}
            </a>
            .
          </p>
        </Container>
      </section>
    </>
  );
}
